<script setup lang="ts">
import{CHANNEL_MODE_LABELS,type ChannelMode}from'../../core/models';defineProps<{duration:number;start:number;end:number;channelMode:ChannelMode;modes:ChannelMode[]}>();const emit=defineEmits<{updateStart:[n:number];updateEnd:[n:number];updateMode:[m:ChannelMode];analyze:[]}>();
</script>
<template><section class="stage-card"><span class="kicker">02 / TRIM THE MOMENT</span><h2>留下最有表情的十秒</h2><div class="timeline"><div class="timeline-fill" :style="{left:`${start/duration*100||0}%`,right:`${100-(end/duration*100||0)}%`}"></div></div><div class="range-pair"><label>起点 {{ start.toFixed(1) }}s<input type="range" min="0" :max="Math.max(0,duration-.1)" step=".1" :value="start" @input="emit('updateStart',Number(($event.target as HTMLInputElement).value))"></label><label>终点 {{ end.toFixed(1) }}s<input type="range" :min="Math.min(duration,start+.1)" :max="duration" step=".1" :value="end" @input="emit('updateEnd',Number(($event.target as HTMLInputElement).value))"></label></div><div class="channel-modes"><span>分析声道</span><button v-for="mode in modes" :key="mode" type="button" :data-mode="mode" :class="{active:channelMode===mode}" :disabled="modes.length===1" @click="emit('updateMode',mode)">{{ modes.length>1?CHANNEL_MODE_LABELS[mode]:'单声道（原声道）' }}</button></div><p v-if="modes.length>1" class="channel-hint">双声道按左右能量占比汇合特征，停顿需两侧同时安静才计入；试听与保存仍保留原始声道。</p><p v-else class="channel-hint">单声道音频，按实际存在的声道分析。</p><button data-testid="analyze" class="acid-button" type="button" @click="emit('analyze')">分析这段声音 →</button></section></template>
